using System.Collections.Generic;public class MedianFinder{PriorityQueue<int,int>lo=new(),hi=new();public MedianFinder(){}public void AddNum(int x){if(lo.Count==0||x<=lo.Peek())lo.Enqueue(x,-x);else hi.Enqueue(x,x);if(lo.Count>hi.Count+1){int v=lo.Dequeue();hi.Enqueue(v,v);}else if(hi.Count>lo.Count){int v=hi.Dequeue();lo.Enqueue(v,-v);}}public double FindMedian()=>lo.Count==hi.Count?((double)lo.Peek()+hi.Peek())/2:lo.Peek();}
